CREATE SCHEMA IF NOT EXISTS scholarship_q10; SET search_path TO scholarship_q10,public;
CREATE TABLE IF NOT EXISTS students(student_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_number TEXT UNIQUE NOT NULL,full_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS applications(application_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id INT NOT NULL REFERENCES students,age_at_application INT NOT NULL CHECK(age_at_application>0),monthly_income NUMERIC(12,2) NOT NULL CHECK(monthly_income>=0),average_mark NUMERIC(5,2) NOT NULL CHECK(average_mark BETWEEN 0 AND 100),submitted_on DATE NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','REJECTED')));
CREATE TABLE IF NOT EXISTS decision_audit(audit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_id BIGINT NOT NULL REFERENCES applications,old_status TEXT,new_status TEXT,changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO students VALUES(1,'SCH001','Student One'),(2,'SCH002','Student Two'),(3,'SCH003','Student Three') ON CONFLICT DO NOTHING;
INSERT INTO applications(application_id,student_id,age_at_application,monthly_income,average_mark,submitted_on,status) VALUES(1,1,18,3000,70,CURRENT_DATE-6,'PENDING'),(2,1,25,2500,85,CURRENT_DATE-5,'PENDING'),(3,2,17,2000,90,CURRENT_DATE-4,'PENDING'),(4,2,22,3001,80,CURRENT_DATE-3,'PENDING'),(5,3,24,2800,69.99,CURRENT_DATE-2,'PENDING'),(6,3,26,1000,95,CURRENT_DATE-1,'PENDING') ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION fn_scholarship_eligible(p_age INT,p_income NUMERIC,p_mark NUMERIC) RETURNS BOOLEAN LANGUAGE plpgsql AS $$
BEGIN IF p_age IS NULL OR p_income IS NULL OR p_mark IS NULL OR p_age<=0 OR p_income<0 OR p_mark<0 OR p_mark>100 THEN RAISE EXCEPTION 'Invalid eligibility input'; END IF; RETURN p_age BETWEEN 18 AND 25 AND p_income<=3000 AND p_mark>=70; END $$;
CREATE OR REPLACE FUNCTION fn_decision_audit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO decision_audit(application_id,old_status,new_status) VALUES(NEW.application_id,OLD.status,NEW.status); END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_decision_audit ON applications;
CREATE TRIGGER trg_decision_audit AFTER UPDATE ON applications FOR EACH ROW EXECUTE FUNCTION fn_decision_audit();
CREATE OR REPLACE PROCEDURE pr_assess_application(p_application_id BIGINT) LANGUAGE plpgsql AS $$
DECLARE a applications%ROWTYPE; BEGIN SELECT * INTO a FROM applications WHERE application_id=p_application_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown application %',p_application_id; END IF; IF a.status<>'PENDING' THEN RAISE EXCEPTION 'Application has already been assessed'; END IF; UPDATE applications SET status=CASE WHEN fn_scholarship_eligible(a.age_at_application,a.monthly_income,a.average_mark) THEN 'APPROVED' ELSE 'REJECTED' END WHERE application_id=p_application_id; END $$;
CREATE OR REPLACE PROCEDURE pr_assess_pending() LANGUAGE plpgsql AS $$
DECLARE a RECORD; BEGIN FOR a IN SELECT application_id FROM applications WHERE status='PENDING' ORDER BY application_id LOOP CALL pr_assess_application(a.application_id); END LOOP; END $$;
CALL pr_assess_pending();
CREATE OR REPLACE VIEW v_approved_applicants AS SELECT s.student_number,s.full_name,a.average_mark,a.status FROM applications a JOIN students s USING(student_id) WHERE a.status='APPROVED';
CREATE INDEX IF NOT EXISTS ix_applications_status_submitted ON applications(status,submitted_on);
EXPLAIN SELECT * FROM applications WHERE status='PENDING' AND submitted_on BETWEEN CURRENT_DATE-30 AND CURRENT_DATE;
-- Schedule every Monday at 08:00: CALL scholarship_q10.pr_assess_pending().
SELECT * FROM v_approved_applicants; SELECT * FROM decision_audit; SELECT application_id,status FROM applications ORDER BY application_id;